-- Dynamic marketplace category hierarchy.
create table if not exists public.main_categories (
 id bigint generated by default as identity primary key,
 name text not null, slug text not null unique, image text,
 sort_order integer not null default 0, is_active boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.sub_categories (
 id bigint generated by default as identity primary key,
 main_category_id bigint not null references public.main_categories(id) on delete restrict,
 name text not null, slug text not null unique, image text,
 sort_order integer not null default 0, is_active boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(main_category_id,name)
);
alter table public.products add column if not exists sub_category_id bigint references public.sub_categories(id) on delete set null;
create index if not exists idx_sub_categories_parent_order on public.sub_categories(main_category_id,sort_order);
create index if not exists idx_products_sub_category_id on public.products(sub_category_id);
alter table public.main_categories enable row level security;
alter table public.sub_categories enable row level security;
drop policy if exists "Active main categories are public" on public.main_categories;
create policy "Active main categories are public" on public.main_categories for select to anon,authenticated using (is_active or exists (select 1 from public.user_roles ur where ur.user_id=(select auth.uid()) and ur.role in ('owner_admin','sub_admin','admin')));
drop policy if exists "Admins manage main categories" on public.main_categories;
create policy "Admins manage main categories" on public.main_categories for all to authenticated using (exists (select 1 from public.user_roles ur where ur.user_id=(select auth.uid()) and ur.role in ('owner_admin','sub_admin','admin'))) with check (exists (select 1 from public.user_roles ur where ur.user_id=(select auth.uid()) and ur.role in ('owner_admin','sub_admin','admin')));
drop policy if exists "Active sub categories are public" on public.sub_categories;
create policy "Active sub categories are public" on public.sub_categories for select to anon,authenticated using ((is_active and exists (select 1 from public.main_categories mc where mc.id=main_category_id and mc.is_active)) or exists (select 1 from public.user_roles ur where ur.user_id=(select auth.uid()) and ur.role in ('owner_admin','sub_admin','admin')));
drop policy if exists "Admins manage sub categories" on public.sub_categories;
create policy "Admins manage sub categories" on public.sub_categories for all to authenticated using (exists (select 1 from public.user_roles ur where ur.user_id=(select auth.uid()) and ur.role in ('owner_admin','sub_admin','admin'))) with check (exists (select 1 from public.user_roles ur where ur.user_id=(select auth.uid()) and ur.role in ('owner_admin','sub_admin','admin')));
grant select on public.main_categories,public.sub_categories to anon,authenticated;
grant insert,update,delete on public.main_categories,public.sub_categories to authenticated;
grant usage,select on all sequences in schema public to authenticated;
insert into public.main_categories(name,slug,sort_order) values ('ফ্যাশন','fashion',1),('গ্যাজেট','gadget',2),('হোম','home',3) on conflict(slug) do update set name=excluded.name,sort_order=excluded.sort_order;
with seed(parent_slug,name,slug,sort_order) as (values
('fashion','পুরুষদের ফ্যাশন','mens-fashion',1),('fashion','নারীদের ফ্যাশন','womens-fashion',2),('fashion','কিডস ফ্যাশন','kids-fashion',3),('fashion','জুতা','shoes',4),('fashion','ব্যাগ ও এক্সেসরিজ','bags-accessories',5),
('gadget','মোবাইল এক্সেসরিজ','mobile-accessories',1),('gadget','হেডফোন ও স্পিকার','headphones-speakers',2),('gadget','স্মার্ট গ্যাজেট','smart-gadgets',3),('gadget','কম্পিউটার ও গেমিং','computer-gaming',4),
('home','হোম ডেকর ও লাইটিং','home-decor-lighting',1),('home','কিচেন ও ডাইনিং','kitchen-dining',2),('home','বেডরুম ও বাথরুম','bedroom-bathroom',3),('home','ফার্নিচার ও অর্গানাইজার','furniture-organizers',4))
insert into public.sub_categories(main_category_id,name,slug,sort_order) select mc.id,s.name,s.slug,s.sort_order from seed s join public.main_categories mc on mc.slug=s.parent_slug on conflict(slug) do update set name=excluded.name,main_category_id=excluded.main_category_id,sort_order=excluded.sort_order;
